Addressed visible stage operands and labels: f=x+10y² · x=1 | gradient=(1,20y) · compare edits | x→0 versus y→1. Controls: At y=0, At y=.1, Reset. Changed computed rows: (x,y)=(1,0) · f=1 / local gradient=(1,0) / finite x→0: |Δf|=1 / finite y→1: |Δf|=10 | (x,y)=(1,0.1) · f=1.1 / local gradient=(1,2) / finite x→0: |Δf|=1 / finite y→1: |Δf|=9.9. Retained computed witnesses: y0: ∇y=0 finiteΔ=10 | y0.1: ∇y=2 finiteΔ=9.9. Numeric display is rounded to three decimals unless explicitly shown otherwise; source computations retain full precision. Exact expressions: // Bounded owner construction; no external model or shared runtime engine.
export const sum=(a:number[])=>a.reduce((s,x)=>s+x,0);
export const dot=(a:number[],b:number[])=>sum(a.map((x,i)=>x*b[i]));
export const f=(x:number)=>Number.isFinite(x)?String(Number(x.toFixed(3))):'∞';
export function compute(mode:number){
const x=1,y=mode?.1:0,F=(a:number,b:number)=>a+10*b*b,base=F(x,y),gx=1,gy=20*y,dx=Math.abs(F(0,y)-base),dy=Math.abs(F(x,1)-base);return{values:[base,gx,gy,dx,dy],rows:[`(x,y)=(${x},${y}) · f=${f(base)}`,`local gradient=(${gx},${f(gy)})`,`finite x→0: |Δf|=${f(dx)}`,`finite y→1: |Δf|=${f(dy)}`],receipt:`y${y}: ∇y=${f(gy)} finiteΔ=${f(dy)}`};
}
